gate loops
task is_woodall(x: int) returns (r: bool)
  ensures r == (exists n in [1, 1000) . n * 2^n - 1 == x)
{
  r := false;
  var n: int := 1;
  var p2: int := 2;
  while n * p2 - 1 <= x
    invariant n >= 1
    invariant p2 == 2^n
    invariant (forall k in [1, n) . k * 2^k - 1 != x) ==> r == false
    decreases x - (n * p2 - 1)
  {
    if n * p2 - 1 == x {
      r := true;
    } else {
    }
    n := n + 1;
    p2 := p2 * 2;
  }
}
```

